contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 firstAmount, uint256 secondAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (firstAmount) + (secondAmount)); require(firstAmount <= 1000000000000000000000000000000); require(secondAmount <= 1000000000000000000000000000000);
        require(firstAmount <= address(this).balance);
        require(secondAmount <= address(this).balance - firstAmount);

        uint256 beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractValue = address(c).balance;

        c.Deposit{value: firstAmount}(); if (__ESBMC_reverted()) return;

        uint256 midBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 midContractValue = address(c).balance;

        c.Deposit{value: secondAmount}(); if (__ESBMC_reverted()) return;

        uint256 afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractValue = address(c).balance;

        assert(
            midBalance == beforeBalance + firstAmount &&
            midContractValue == beforeContractValue + firstAmount &&
            afterBalance == midBalance + secondAmount &&
            afterContractValue == midContractValue + secondAmount
        );
    }

    receive() external payable {}
}

