pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 firstAmount, uint256 secondAmount) internal {
        firstAmount = bound(firstAmount, 0, 1000000000000000000000000000000);
        secondAmount = bound(secondAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(firstAmount <= address(this).balance);
        vm.assume(secondAmount <= address(this).balance - firstAmount);
        uint256 beforeBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeContractValue = address(c).balance;
        try c.Deposit{value: firstAmount}() {} catch { return; }
        uint256 midBalance;
        try c.balances(address(this)) returns (uint256 __r) { midBalance = __r; } catch { return; }
        uint256 midContractValue = address(c).balance;
        try c.Deposit{value: secondAmount}() {} catch { return; }
        uint256 afterBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 afterContractValue = address(c).balance;
        assertTrue(midBalance == beforeBalance + firstAmount &&
            midContractValue == beforeContractValue + firstAmount &&
            afterBalance == midBalance + secondAmount &&
            afterContractValue == midContractValue + secondAmount);
    }

    function testFuzz_run(uint256 firstAmount, uint256 secondAmount) public {
        _run(firstAmount, secondAmount);
    }

    receive() external payable {}
}
